  XW += x[32] * 2.0132999999999998e+02; // C12H25O2
  XW += x[33] * 2.1632100000000003e+02; // OC12H23OOH
  XW += x[34] * 2.8013999999999999e+01; // N2
  // Now compute conversion
  amrex::Real XWinv = 1.0 / XW;
  y[0] = x[0] * 1.7034000000000000e+02 * XWinv;
  y[1] = x[1] * 1.0080000000000000e+00 * XWinv;
