  y[8] = x[8] * 3.1998000000000001e+01 * XWinv;
  y[9] = x[9] * 1.5035000000000000e+01 * XWinv;
  y[10] = x[10] * 1.6042999999999999e+01 * XWinv;
  y[11] = x[11] * 3.0026000000000000e+01 * XWinv;
  y[12] = x[12] * 2.8009999999999998e+01 * XWinv;
  y[13] = x[13] * 4.4009000000000000e+01 * XWinv;
  y[14] = x[14] * 2.6037999999999997e+01 * XWinv;
  y[15] = x[15] * 2.8053999999999998e+01 * XWinv;
